// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract MockVault {
    function totalWeight() external pure returns (uint) { return 6; }
    function getMemberWeight(address) external pure returns (uint) { return 6; }
}

contract InvMutTest is Test {
    DAO c;
    MockVault vault;

    function setUp() public {
        c = new DAO();
        vault = new MockVault();
        c.init(address(0x1111), address(0x2222), address(vault));
    }

    function testFuzz_run() public {
        c.newGrantProposal(address(0xBEEF), 100);
        uint id = c.proposalCount();

        c.voteProposal(id);
        require(c.mapPID_finalising(id), "setup: not finalising");

        bool reverted;
        try c.cancelProposal(id, id) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}
